package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class PublicDecimalProductsTest {
 private static Question q(String prompt){return new Question("decimalMul",prompt,"private expression","999");}
 private static Checker.Result check(Question q,String input){return new Checker().check(q,List.of(),Collections.singletonList(input));}
 @Test public void BroadPublicProductsRetainOriginalsAndUseExactArithmeticWithoutStoredKeys(){
  for(String[] row:new String[][]{{"100.25 × 24","2406"},{"1.0001 * 24","24.0024"},{"0.000000000001 × 0.000000000001","0.000000000000000000000001"},{"99.999 × 99","9899.901"},{"0.000 × 99","0"},{"4.15 × 0.2","0.83"},{"1.25 × 1000","1250"},{"00000.500 × 000000001","0.5"}}){Question q=q(row[0]);var v=DecimalWholeProducts.readGeneral(q);assertNotNull(v);assertEquals(0,new BigDecimal(row[1]).compareTo(v.value()));assertTrue(check(q,row[1]).correct());assertFalse(check(q,new BigDecimal(row[1]).add(BigDecimal.ONE).toPlainString()).correct());q.expression=null;q.answers=null;assertTrue(check(q,row[1]).correct());assertTrue(CurriculumLimits.NONE.allows(q));assertEquals(row[0],q.prompt);}
  var raw=DecimalWholeProducts.readGeneral(q("00012.3400 × 000002.50"));assertEquals("00012.3400",raw.leftRaw());assertEquals("000002.50",raw.rightRaw());assertFalse(raw.wholeRight());assertNull(DecimalWholeProducts.read(q("100.25 × 24")));assertNotNull(DecimalWholeProducts.readGeneral(q("100.25 × 24")));
 }
 @Test public void ReadOnlyGuidesKeepExactLegacySixAndNineFramesAndDrafts(){
  for(String prompt:List.of("3.75 × 24","4.15 × 0.2","3.75 * 24.0")){Question q=q(prompt);q.studyGuide=new StudyGuide().step("private","private","","999");StudyGuide stored=q.studyGuide;Question control=q(prompt);DecimalArithmeticRelations.attach(control);StudyGuide guide=DecimalWholeProducts.guide(q);assertEquals("decimal-arithmetic-relations-v1",guide.teachingVersion);assertEquals(prompt.endsWith("24")?6:9,guide.frames.size());for(int i=0;i<guide.frames.size();i++){StudyGuide.Frame actual=guide.frames.get(i),old=control.studyGuide.frames.get(i);assertEquals(old.instruction,actual.instruction);assertEquals(old.before,actual.before);assertEquals(old.after,actual.after);assertEquals(old.expected,actual.expected);assertEquals(old.inputFormat,actual.inputFormat);}HelpPlan h=HelpPlan.forQuestion(q);assertFalse(h.canTransfer());assertSame(stored,q.studyGuide);assertEquals("private expression",q.expression);assertArrayEquals(new String[]{"999"},q.answers);HelpPlan.Draft draft=h.restore(null,q.id);draft.entries=new ArrayList<>(guide.frames.stream().map(f->f.expected).toList());draft.stage=h.size();HelpPlan.Draft restored=h.restore(draft.copy(),q.id);assertEquals(h.size(),restored.stage);assertEquals("decimal-arithmetic-relations-v1",restored.teachingVersion);assertEquals(0,new BigDecimal(h.enteredAnswer(restored)).compareTo(DecimalWholeProducts.value(q)));}
  Question factory=DecimalWholeProducts.make("3.375",13);StudyGuide stored=factory.studyGuide;assertEquals(6,HelpPlan.forQuestion(factory).size());assertSame(stored,factory.studyGuide);
 }
 @Test public void LargeShiftedProductAndTwentyFourPlaceResultAreReachableWithoutSharedGuardChanges(){
  Question q=q("999999999.999999999999 × 999999999.999999999999");String product="999999999999999999.998000000000000000000001";assertTrue(check(q,product).correct());assertEquals(0,new BigDecimal(product).compareTo(DecimalWholeProducts.value(q)));HelpPlan h=HelpPlan.forQuestion(q);List<String> values=List.of("999999999.999999999999","999999999.999999999999","12","12","999999999999999999999","999999999999999999999","999999999999999999998000000000000000000001","24",product);assertEquals(9,h.size());for(int i=0;i<values.size();i++)assertTrue("frame"+i,h.step(i).accepts(values.get(i)));assertTrue(h.step(2).accepts("12/1"));assertTrue(h.step(6).accepts(values.get(6)+".0"));assertFalse(h.step(6).accepts(values.get(6)+"/1"));assertFalse(h.step(8).accepts("999999999999999999.998000000000000000000002"));assertTrue(DecimalWholeProducts.references(q,8,values.subList(0,8)).containsValue(values.get(6)));try{Expression.number(values.get(6));fail("Shared30-token guard widened");}catch(IllegalArgumentException expected){}try{Expression.number(product);fail("Shared12-decimal-place guard widened");}catch(IllegalArgumentException expected){}assertFalse(h.step(6).accepts("1".repeat(121)));
 }
 @Test public void ReferencesOnlyShowCheckedLearnerInputsWithFullOriginalLabels(){
  Question q=q("3.75 × 24");List<String> entries=List.of("3.750","024","2","375","9000");assertEquals(Map.of("왼쪽 정수 A = x의 소수점 p칸 이동 = ","375","오른쪽 수 y = ","024"),DecimalWholeProducts.references(q,4,entries));assertEquals(Map.of("정수 곱 r = A × y = ","9000","소수 자릿수 p = ","2"),DecimalWholeProducts.references(q,5,entries));assertEquals(Map.of("오른쪽 수 y = ","024"),DecimalWholeProducts.references(q,4,List.of("3.75","024","2","376")));assertTrue(DecimalWholeProducts.references(q,0,entries).isEmpty());assertTrue(DecimalWholeProducts.references(q,6,entries).isEmpty());
  Question decimal=q("4.15 × 0.2");List<String> values=List.of("4.15","0.20","2","1","415","2","830","3");assertEquals(Map.of("왼쪽 정수 A = x의 소수점 p칸 이동 = ","415","오른쪽 정수 B = y의 소수점 q칸 이동 = ","2"),DecimalWholeProducts.references(decimal,6,values));assertEquals(Map.of("정수 곱 r = A × B = ","830","돌려놓을 자릿수 k = p + q = ","3"),DecimalWholeProducts.references(decimal,8,values));assertTrue(DecimalWholeProducts.references(decimal,8,List.of("4.15","0.2","2","1","415","2","831","4")).isEmpty());assertTrue(DecimalWholeProducts.references(null,0,values).isEmpty());assertTrue(DecimalWholeProducts.references(q,3,null).isEmpty());
 }
 @Test public void OptionalWorkIsCheckedAgainstPublicProductWithExistingFullAndPartialRoles(){
  Question q=q("3.75 × 24");q.kind="complexRoots";q.calculationMethod="written";Checker checker=new Checker();assertTrue(checker.check(q,List.of("3.75*24=90"),List.of("90"),List.of(Checker.StepKind.FULL)).correct());assertTrue(checker.checkSteps(q,List.of("3.75*24=90"),List.of(Checker.StepKind.FULL)).correct());Checker.Result wrong=checker.check(q,List.of("999=999"),List.of("90"),List.of(Checker.StepKind.FULL));assertEquals(Checker.Status.WRONG_STEP,wrong.status);assertEquals(Checker.InputTarget.WORK,wrong.inputTarget);assertEquals(0,wrong.index);Checker.Result incomplete=checker.check(q,List.of("3.75*24="),List.of("90"),List.of(Checker.StepKind.FULL));assertEquals(Checker.Status.INPUT_NEEDED,incomplete.status);assertEquals(Checker.InputTarget.WORK,incomplete.inputTarget);assertTrue(checker.check(q,List.of("2*3=6"),List.of("90"),List.of(Checker.StepKind.PARTIAL)).correct());assertEquals("private expression",q.expression);assertEquals("complexRoots",q.kind);assertArrayEquals(new String[]{"999"},q.answers);q.stepSupport=false;assertEquals(Checker.Status.INPUT_NEEDED,checker.check(q,List.of("3.75*24=90"),List.of("90"),List.of(Checker.StepKind.FULL)).status);assertTrue(checker.check(q,List.of("2*3=6"),List.of("90"),List.of(Checker.StepKind.PARTIAL)).correct());
 }
 @Test public void SourceAndNumericGuardsCannotFallBackToStoredGuideOrAnswer(){
  for(String prompt:List.of("1000000000 × 2","1.2345678901234 × 2","1 × 1.2345678901234","-1 × 2","1e2 × 2","1. × 2","1 × .2","1 × 2 × 3","1/2 × 2","1 ÷ 2","1,2 × 2","1 × "+"9".repeat(260))){Question q=q(prompt);q.studyGuide=new StudyGuide().step("private","private","","999");StudyGuide original=q.studyGuide;assertNull(DecimalWholeProducts.readGeneral(q));assertNull(DecimalWholeProducts.value(q));assertNull(DecimalWholeProducts.guide(q));assertNull(DecimalWholeProducts.workQuestion(q));assertNull(HelpPlan.forQuestion(q));assertSame(original,q.studyGuide);assertEquals(Checker.Status.INPUT_NEEDED,check(q,"999").status);assertFalse(CurriculumLimits.NONE.allows(q));}
  Question q=q("0.5 × 2");q.answerFormat="decimalValue";assertTrue(check(q,"1").correct());assertTrue(check(q,"1.000").correct());assertTrue(check(q," 1 . 000 ").correct());assertEquals(Checker.Status.WRONG_ANSWER,check(q,"–1").status);q.answerFormat="decimal";assertEquals(Checker.Status.INPUT_NEEDED,check(q,"1").status);assertTrue(check(q,"1.0").correct());for(String bad:List.of("1/1","1+0","1e0","1,0","1.","1".repeat(121),"1".repeat(241)))assertEquals(bad,Checker.Status.INPUT_NEEDED,check(q,bad).status);assertEquals(Checker.Status.INPUT_NEEDED,check(q,null).status);assertNull(DecimalWholeProducts.readGeneral(null));assertNull(DecimalWholeProducts.readGeneral(new Question("decimalDiv","1 × 2","","2")));
 }
}
